python3 -B -c 'import json,pathlib,gzip
P=pathlib.Path
p=P("/proc/config.gz")
out={"boot_id":P("/proc/sys/kernel/random/boot_id").read_text().strip(),"kernel":P("/proc/sys/kernel/osrelease").read_text().strip(),"nfsd_filesystem_registered":"nfsd" in P("/proc/filesystems").read_text().split(),"kernel_config_available":p.exists(),"nfs_export_entry_count":0}
if p.exists():
 out["kernel_config"]=[l for l in gzip.decompress(p.read_bytes()).decode().splitlines() if any(s in l for s in ["CONFIG_NFSD","CONFIG_NFS_FS","CONFIG_TCG_","CONFIG_OF_OVERLAY"])]
for f in [P("/etc/exports")]+list(P("/etc/exports.d").glob("*.exports")):
 if f.is_file(): out["nfs_export_entry_count"]+=sum(bool(l.strip()) and not l.lstrip().startswith("#") for l in f.read_text().splitlines())
print(json.dumps(out,indent=2))'

python3 -B -c 'import json,pathlib,shutil
P=pathlib.Path
out={"tools":{s:shutil.which(s) for s in ["tpm2_getcap","tpm2_startup","tpm2_clear"]},"devices":{str(p):p.exists() for p in [P("/dev/tpm0"),P("/dev/tpmrm0")]},"sysfs":{}}
for t in P("/sys/class/tpm").glob("tpm*"):
 info={"device":str((t/"device").resolve()),"driver":str((t/"device/driver").resolve())}
 for p in [t/"tpm_version_major",t/"device/of_node/compatible",t/"device/of_node/status"]:
  if p.exists(): info[str(p)]=p.read_bytes().decode(errors="replace").replace("\0","|")
 out["sysfs"][t.name]=info
print(json.dumps(out,indent=2))'
